<script setup lang="ts">
import { computed, onBeforeUnmount } from 'vue';
import type { FlightControlKey, LaunchFlightSnapshot } from '../../contracts';
const props=defineProps<{flight:Readonly<LaunchFlightSnapshot>;paused:boolean}>();
const emit=defineEmits<{ignite:[];hold:[key:FlightControlKey,down:boolean];nudge:[key:FlightControlKey];throttle:[value:number];pause:[];reset:[]}>();
const fuel=computed(()=>Math.round(props.flight.fuel/210000*100));
const status=computed(()=>props.paused?'PAUSED':props.flight.spaceReached?'SPACE REACHED':!props.flight.ignited?'READY ON PAD':props.flight.altitude<10000?'LIFTOFF':props.flight.altitude<45000?'CLIMBING':'ABOVE THE CLOUDS');
const keys=[['KeyW','W','Thrust +'],['KeyS','S','Thrust −'],['KeyA','A','Steer left'],['KeyD','D','Steer right']] as const;
function down(event:PointerEvent,key:FlightControlKey){(event.currentTarget as Element).setPointerCapture(event.pointerId);emit('hold',key,true);}
onBeforeUnmount(()=>keys.forEach(([key])=>emit('hold',key,false)));
</script>
<template>
 <section class="launch-controls" aria-label="Live rocket controls">
  <div class="flight-strip"><span class="route">EARTH <span aria-hidden="true">↗</span> SPACE</span><strong role="status">{{ status }}</strong><progress :value="flight.altitude" max="100000" aria-label="Climb to 100 kilometres"/></div>
  <div class="telemetry" aria-label="Live ascent telemetry">
   <div><small>ALTITUDE</small><strong data-flight-altitude>{{ (flight.altitude/1000).toFixed(1) }} <em>km</em></strong></div>
   <div><small>CLIMB</small><strong data-flight-speed>{{ Math.round(flight.verticalSpeed) }} <em>m/s</em></strong></div>
   <div><small>FUEL</small><strong>{{ fuel }} <em>%</em></strong></div>
  </div>
  <div class="attitude" aria-label="Rocket tilt"><i :style="{transform:`rotate(${flight.pitch}deg)`}">↑</i><span>{{ Math.abs(flight.pitch).toFixed(0) }}° {{ flight.pitch<-.5?'LEFT':flight.pitch>.5?'RIGHT':'UPRIGHT' }}</span></div>
  <button v-if="!flight.ignited" class="ignite" :disabled="paused" @click="emit('ignite')"><kbd>SPACE</kbd> Ignite engines</button>
  <div class="pilot-pad">
   <label class="throttle">THRUST <strong>{{ Math.round(flight.throttle*100) }}%</strong><input type="range" min="0" max="100" :value="flight.throttle*100" :disabled="paused||flight.spaceReached" aria-label="Rocket throttle" @input="emit('throttle',Number(($event.target as HTMLInputElement).value)/100)"/></label>
   <div class="keys"><button v-for="[key,label,action] in keys" :key="key" :aria-label="action" :disabled="paused||flight.spaceReached" @pointerdown="down($event,key)" @pointerup="emit('hold',key,false)" @pointercancel="emit('hold',key,false)" @lostpointercapture="emit('hold',key,false)" @click="emit('nudge',key)"><kbd>{{ label }}</kbd><span>{{ action }}</span></button></div>
   <div class="actions"><span>Hold to fly · 8× time</span><button :aria-label="paused?'Resume flight':'Pause flight'" @click="emit('pause')">{{ paused?'▶':'Ⅱ' }}</button><button aria-label="Reset launch" @click="emit('reset')">↺</button></div>
  </div>
 </section>
</template>
